import unittest
from solution import tail

class ContractTests(unittest.TestCase):
    def test_00(self):
        self.assertEqual(tail([('a',2),('b',4),('c',1)],5), [('b',4),('c',1)])
    def test_01(self):
        self.assertEqual(tail([('a',1),('b',9)],3), [])
    def test_02(self):
        self.assertEqual(tail([('a',0)],0), [('a',0)])
    def test_03(self):
        with self.assertRaises(ValueError): tail([],-1)

